steps.action:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"{ __schema { types { name fields { name args { name } } inputFields { name } } } }"}' | python3 -c "
import sys,json
d=json.load(sys.stdin)
for t in d['data']['__schema']['types']:
    if not t['name'] or t['name'].startswith('__'):
        continue
    if t.get('fields'):
        for f in t['fields']:
            if 'creator' in f['name'].lower():
                print('QUERY FIELD:', t['name'], '->', f['name'])
    if t.get('inputFields'):
        for f in t['inputFields']:
            if 'creator' in f['name'].lower():
                print('INPUT FIELD:', t['name'], '->', f['name'])
"
